query:
SELECT w.id, w.title, w.title_ar, w.provider, w.date, w.time_start, w.time_end, w.price, w.capacity, w.registered_count, w.description
FROM workshops w
ORDER BY w.date, w.time_start;

SELECT a.id, a.name, a.name_ar, a.description, a.sponsor, a.prize_value, a.prize_currency
FROM awards a
ORDER BY a.id;

SELECT ks.id, ks.full_name, ks.title, ks.affiliation, ks.speaker_sector, ks.photo_url, ks.presentation_title, ks.sort_order
FROM keynote_speakers ks
ORDER BY ks.sort_order, ks.id;

